// osascript -l JavaScript dump_menus.js <pid> [skip-apple]
// Prints every menu-bar item of the process, indented, with "(grey)" for disabled ones.
function run(argv) {
  const pid = parseInt(argv[0], 10);
  const se = Application("System Events");
  const procs = se.processes.whose({ unixId: pid });
  if (procs.length === 0) return "no process " + pid;
  const proc = procs[0];
  const out = [];
  function walk(menu, depth) {
    const items = menu.menuItems;
    const titles = items.title();
    const enabled = items.enabled();
    let chars = [], mods = [];
    try { chars = items.attributes.byName("AXMenuItemCmdChar").value(); } catch (e) {}
    try { mods = items.attributes.byName("AXMenuItemCmdModifiers").value(); } catch (e) {}
    for (let i = 0; i < titles.length; ++i) {
      const title = titles[i];
      if (!title) { out.push("  ".repeat(depth) + "---"); continue; }
      let key = "";
      const c = chars[i];
      if (c) {
        const m = mods[i];
        key = "  [" + ({0: "Cmd+", 1: "Shift+Cmd+", 2: "Opt+Cmd+", 3: "Shift+Opt+Cmd+", 4: "Ctrl+Cmd+", 8: ""}[m] ?? ("mod" + m + "+")) + c + "]";
      }
      out.push("  ".repeat(depth) + title + key + (enabled[i] ? "" : "  (grey)"));
      let subs = 0;
      try { subs = items[i].menus.length; } catch (e) {}
      if (subs > 0) walk(items[i].menus[0], depth + 1);
    }
  }
  const tops = proc.menuBars[0].menuBarItems;
  const names = tops.title();
  for (let i = 0; i < names.length; ++i) {
    if (argv[1] && names[i] === "Apple") continue;
    out.push("== " + names[i]);
    try { walk(tops[i].menus[0], 1); } catch (e) { out.push("  (unreadable: " + e + ")"); }
  }
  return out.join("\n");
}
