190	    bar->Insert(view_at + 1, print, _L("Print"));
191	    m_bar_menus.push_back(print);
192	    bar->Insert(view_at + 2, printer, _L("Printer"));
193	    m_bar_menus.push_back(printer);
194	#else
195	    std::vector<wxMenuItem*> items;
196	    for (wxMenuItem* item : top_items) {
197	        items.push_back(item);
198	        if (item->GetSubMenu() == m_view) {
199	            items.push_back(submenu(top, print, _L("Print")));
200	            items.push_back(submenu(top, printer, _L("Printer")));
201	        }
202	    }
203	    arrange(top, items);
204	#endif
205	    m_print   = print;
206	    m_printer = printer;
207	
208	    m_file->Bind(wxEVT_MENU_OPEN, &AppMenus::on_file_menu_open, this);
209	    fill_open_recent();
210	    // MainFrame's own key hook takes these shortcuts for OrcaSlicer's
211	    // commands, and the handler bound last runs first. The shell installs
212	    // during MainFrame's constructor, before that hook is bound, so this
213	    // binds once the constructor is done.
214	    CallAfter([this] {
215	        if (m_installed)
216	            m_frame.Bind(wxEVT_CHAR_HOOK, &AppMenus::on_char_hook, this);
217	    });
218	}
