220	void AppMenus::uninstall()
221	{
222	    if (!m_installed)
223	        return;
224	    m_installed = false;
225	    m_frame.Unbind(wxEVT_CHAR_HOOK, &AppMenus::on_char_hook, this);
226	    if (m_file != nullptr)
227	        m_file->Unbind(wxEVT_MENU_OPEN, &AppMenus::on_file_menu_open, this);
228	    if (m_recent != nullptr)
229	        for (const auto& [id, project] : m_recent_projects)
230	            m_recent->Unbind(wxEVT_MENU, &AppMenus::on_recent, this, id);
231	    m_recent_projects.clear();
232	    for (const auto& [menu, id] : m_bound) {
233	        menu->Unbind(wxEVT_MENU, &AppMenus::on_command, this, id);
234	        m_frame.Unbind(wxEVT_UPDATE_UI, &AppMenus::on_update_ui, this, id);
235	    }
236	    m_bound.clear();
237	    m_commands.clear();
238	
239	    // Last change first, so each menu goes back to the items it had.
240	    for (auto it = m_arranged.rbegin(); it != m_arranged.rend(); ++it)
241	        arrange(it->menu, it->items);
242	    m_arranged.clear();
243	    for (wxMenuItem* item : m_placed)
244	        delete item;
245	    m_placed.clear();
246	#ifdef __APPLE__
247	    wxMenuBar* bar = m_frame.GetMenuBar();
248	    for (wxMenu* menu : m_bar_menus)
249	        for (size_t at = 0; at < bar->GetMenuCount(); ++at)
250	            if (bar->GetMenu(at) == menu) {
251	                delete bar->Remove(at);
252	                break;
253	            }
254	#endif
255	    m_bar_menus.clear();
256	    if (m_relabeled != nullptr)
257	        m_relabeled->SetItemLabel(m_relabeled_from);
258	    m_relabeled = nullptr;
259	    m_file = m_view = m_help = m_print = m_printer = m_recent = nullptr;
260	    m_recent_item = nullptr;
261	}
