263	bool AppMenus::run_shortcut(const wxKeyEvent& event)
264	{
265	    int id = 0;
266	    const int key = event.GetKeyCode();
267	    if (event.GetModifiers() == wxMOD_CMD) {
268	        if (key == 'N')
269	            id = m_new_project;
270	        else if (key == 'O')
271	            id = m_open;
272	        else if (key == 'S')
273	            id = m_save;
274	        else if (key == 'R')
275	            id = m_slice;
276	    } else if (event.GetModifiers() == (wxMOD_CMD | wxMOD_SHIFT) && key == 'S') {
277	        id = m_export_project;
278	    }
279	    if (id == 0)
280	        return false;
281	    run(id);
282	    return true;
283	}
