287	wxMenuItem* AppMenus::command(wxMenu* menu, const wxString& label, Command command, bool check)
288	{
289	    auto* item = new wxMenuItem(menu, wxID_ANY, label, wxEmptyString, check ? wxITEM_CHECK : wxITEM_NORMAL);
290	    const int id = item->GetId();
291	    // On the menu, as OrcaSlicer binds its own items off Windows; the frame
292	    // answers the update events, which wx sends to the window.
293	    menu->Bind(wxEVT_MENU, &AppMenus::on_command, this, id);
294	    m_frame.Bind(wxEVT_UPDATE_UI, &AppMenus::on_update_ui, this, id);
295	    m_bound.emplace_back(menu, id);
296	    m_commands.emplace(id, std::move(command));
297	    return item;
298	}
