310	// Makes `menu` hold `items`, in order. An item of the menu not among them is
311	// taken out and kept; one not yet in it is put in. An item already in its
312	// place is left alone. Every new item of a stock menu is recorded, to be
313	// deleted once uninstall has taken it out again.
314	void AppMenus::arrange(wxMenu* menu, const std::vector<wxMenuItem*>& items)
315	{
316	    if (m_installed) {
317	        m_arranged.push_back({menu, items_of(menu)});
318	        for (wxMenuItem* item : items)
319	            if (!holds(menu, item))
320	                m_placed.push_back(item);
321	    }
322	    for (wxMenuItem* item : items_of(menu))
323	        if (std::find(items.begin(), items.end(), item) == items.end())
324	            menu->Remove(item);
325	    for (size_t at = 0; at < items.size(); ++at) {
326	        if (at < menu->GetMenuItemCount() && menu->FindItemByPosition(at) == items[at])
327	            continue;
328	        if (holds(menu, items[at]))
329	            menu->Remove(items[at]);
330	        menu->Insert(at, items[at]);
331	    }
332	}
