334	void AppMenus::build_file(wxMenu* menu)
335	{
336	    wxMenuItem* import_item = stock_item(menu, _L("Import"));
337	    wxMenuItem* export_item = stock_item(menu, _L("Export"));
338	    wxMenu*     exports     = export_item->GetSubMenu();
339	#ifdef __APPLE__
340	    wxMenuItem* quit        = menu->FindChildItem(wxID_EXIT);
341	#else
342	    // A Shortcut::Quit item, whose id is not wxID_EXIT, off macOS.
343	    wxMenuItem* quit        = stock_item(menu, _L("Quit"));
344	#endif
345	    if (exports == nullptr || quit == nullptr)
346	        throw std::runtime_error("OrcaSlicer's File menu has no Export submenu or no Quit item");
347	
348	    // JusPrin keeps every project in its own store and saves as it goes, so
349	    // File opens and saves that store's projects. OrcaSlicer's Open Project,
350	    // Recent files and Save Project read and write the 3MF at its own path;
351	    // a 3MF leaves the store only through Export.
352	    wxMenuItem* new_project = command(menu, _L("New project") + "\tCtrl+N", {[this] {
353	        m_shell.home_view()->backend().new_project();
354	    }});
355	    m_new_project = new_project->GetId();
356	    wxMenuItem* open = command(menu, _L("Open…") + "\tCtrl+O", {[this] {
357	        m_shell.home_view()->backend().open_file();
358	    }});
359	    m_open = open->GetId();
360	    m_recent      = new wxMenu();
361	    m_recent_item = submenu(menu, m_recent, _L("Open recent"));
362	    // Enabled from the list fill_open_recent last read.
363	    m_frame.Bind(wxEVT_UPDATE_UI, &AppMenus::on_update_ui, this, m_recent_item->GetId());
364	    m_bound.emplace_back(menu, m_recent_item->GetId());
365	    m_commands.emplace(m_recent_item->GetId(), Command{{}, [this] { return !m_recent_projects.empty(); }});
366	
367	    // Saves now and pins that version, so it is kept, and Version history
368	    // lists it.
369	    wxMenuItem* save = command(menu, _L("Save") + "\tCtrl+S", {[this] {
370	        m_shell.autosave()->pin_current();
371	        m_shell.status_row()->refresh();
372	    }, [this] { return !home() && m_shell.autosave() != nullptr; }});
373	    m_save = save->GetId();
374	    wxMenuItem* versions = command(menu, _L("Version history…"), {[this] {
375	        m_shell.open_project_row(ProjectMenuRow::VersionHistory);
376	    }, [this] { return project_shown(); }});
377	
378	    wxMenuItem* project     = command(exports, _L("Project 3MF…") + "\tCtrl+Shift+S", {[this] {
379	        m_shell.open_project_row(ProjectMenuRow::Export);
380	    }, [this] { return !home() && m_shell.autosave() != nullptr; }});
381	    m_export_project = project->GetId();
382	    // One export for the project and one for the sliced plate. OrcaSlicer's
383	    // other exports (meshes, a 3MF without its extensions, the Bambu sliced
384	    // 3MF, toolpaths, preset bundles) stay in classic view.
385	    arrange(exports, {project, separator(exports), stock_item(exports, _L("Export G-code") + dots)});
386	
387	    std::vector<wxMenuItem*> items{new_project, open,        m_recent_item, separator(menu), save,
388	                                   versions,    separator(menu), import_item, export_item};
389	#ifndef __APPLE__
390	    // The Mac keeps Quit in the app menu and hides it here, where a
391	    // separator before it would end the menu.
392	    items.push_back(separator(menu));
393	#endif
394	    items.push_back(quit);
395	    arrange(menu, items);
396	#ifdef _WIN32
397	    // Windows names it Exit.
398	    m_relabeled      = quit;
399	    m_relabeled_from = quit->GetItemLabel();
400	    quit->SetItemLabel(_L("Exit"));
401	#endif
402	}
