556	// The saved projects as Home lists them, newest first. Read when File opens,
557	// not on every update: reading the store touches each project's folder.
558	void AppMenus::fill_open_recent()
559	{
560	    for (const auto& [id, project] : m_recent_projects)
561	        m_recent->Unbind(wxEVT_MENU, &AppMenus::on_recent, this, id);
562	    m_recent_projects.clear();
563	    while (m_recent->GetMenuItemCount() > 0)
564	        m_recent->Destroy(m_recent->FindItemByPosition(0));
565	
566	    Workspace::ProjectAutosave* autosave = m_shell.autosave();
567	    const auto projects = autosave != nullptr ? autosave->projects() : std::nullopt;
568	    if (projects)
569	        for (const auto& project : *projects) {
570	            if (m_recent_projects.size() == kRecentProjects)
571	                break;
572	            wxString name = project.name.empty() || project.name == _u8L("Untitled") ? _L("Untitled project")
573	                                                                                     : wxString::FromUTF8(project.name);
574	            name.Replace("&", "&&");
575	            wxMenuItem* item = m_recent->Append(wxID_ANY, name);
576	            m_recent->Bind(wxEVT_MENU, &AppMenus::on_recent, this, item->GetId());
577	            m_recent_projects.emplace(item->GetId(), project.id);
578	        }
579	    m_recent_item->Enable(!m_recent_projects.empty());
580	}
